using System;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
namespace YesterdayConvoy.Editor.Tests
{
    public sealed class BossCoreExtensionTests
    {
        static ManualBattle Fixture(string card,out DeployedUnitState unit,string skill="s3",bool begin=true)
        {
            bool frost=card=="CARD_M14",talulah=card=="CARD_TALULAH_TRIAL";
            var settings=new ManualBattleSettings(card,"fixture-core",100,5,3,1,.2f,5000,.35f,1,30,1,10000);
            var effects=new MonsterEffectSettings(damageType:frost||talulah?CombatDamageType.Arts:CombatDamageType.Physical,frostNova:frost,talulahSecondPhase:talulah,frozenAttackMultiplier:frost?2:0);
            var combat=new EngagementSettings(unitAttack:50,unitArmor:10,unitRange:2.6f,unitInterval:3,defenderHealth:100000,defenderAttack:.01f,defenderArmor:0,defenderRange:3,defenderInterval:10000,initialSP:12,requiredSP:12,spPerSecond:1,skillAmmo:6,skillAttack:105,skillInterval:3.2f,skillRange:2.6f,projectileTime:.1f,attackDuration:1,attackWindup:.4f,effects:effects,fireRain:talulah);
            var guards=new[]{new DefenderSettings("a","甲",null,new Vector3(.6f,0,0),100000,.01f,0,3,10000,1,canAttack:false),new DefenderSettings("b","乙",null,new Vector3(1.2f,0,.5f),100000,.01f,0,3,10000,0,canAttack:false),new DefenderSettings("c","丙",null,new Vector3(1.8f,0,-.3f),100000,.01f,0,3,10000,0,canAttack:false)};
            var battle=new ManualBattle(settings,new[]{Vector3.zero,new Vector3(30,0,0)},new Vector3(8,0,0),combat,roster:guards);battle.ConfigureBossCoreViviSkill(skill);unit=null;if(!begin)return battle;battle.Begin();var receipt=battle.TryDeploy(battle.RunId,1,battle.Entry);Assert.That(receipt.Success,Is.True);unit=battle.FindUnit(receipt.EntityId);return battle;
        }
        [Test]public void ViviEquipsOneSkillBeforeBattleAndS3KeepsExistingSixAmmoEntry()
        {var b=Fixture("CARD_WISADEL_APRIL",out var u);Assert.That(b.UsesBossCoreSkill(u),Is.False);Assert.That(b.BossCoreSkills(u),Is.Empty);Assert.That(b.TryActivateSkill(b.RunId,3,u.EntityId),Is.EqualTo(SkillFailure.None));Assert.That(u.SkillAmmo,Is.EqualTo(6));Assert.That(b.BossRosterObjects.Count(o=>o.Kind=="soul"&&o.Alive),Is.EqualTo(3));Assert.That(b.BossRosterEvents.Single(e=>e.SkillKey=="s3"&&e.Kind=="SkillStart").EndAt,Is.EqualTo(double.PositiveInfinity));Assert.Throws<InvalidOperationException>(()=>b.ConfigureBossCoreViviSkill("s2"));b.Restart();Assert.That(b.BossCoreViviSkill,Is.EqualTo("s3"));Assert.That(b.BossRosterObjects,Is.Empty);}
        [Test]public void ViviS1UsesAttackSpAndAnActualNextAttackThenThreeShocks()
        {var b=Fixture("CARD_WISADEL_APRIL",out var u,"s1");Assert.That(b.BossCoreSkills(u).Single().MaxSP,Is.EqualTo(2));Assert.That(b.BossCoreState(u).SP,Is.Zero);b.Advance(4);Assert.That(b.BossCoreState(u).SP,Is.EqualTo(2));Assert.That(b.TryActivateBossCoreSkill(b.RunId,5,u.EntityId),Is.EqualTo(SkillFailure.None));Assert.That(b.TryActivateBossCoreSkill(b.RunId,5,u.EntityId),Is.EqualTo(SkillFailure.None));Assert.That(u.SkillsUsed,Is.EqualTo(1));b.SetPaused(true);int events=b.BossRosterEvents.Count;float hp=b.Defender.Health;b.Advance(20);Assert.That(b.Defender.Health,Is.EqualTo(hp));Assert.That(b.BossRosterEvents.Count,Is.EqualTo(events));b.SetPaused(false);b.Advance(5);Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="s1"),Is.EqualTo(1));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="s1"&&e.Applied),Is.True);Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="SkillEnd"&&e.SkillKey=="s1"),Is.EqualTo(1));}
        [Test]public void ViviS2NaturallyChargesAndOverloadsThenStopsItsOriginalActivation()
        {var b=Fixture("CARD_WISADEL_APRIL",out var u,"s2");Assert.That(b.BossCoreSkills(u).Single().SP,Is.EqualTo(15));b.Advance(10.1f);Assert.That(b.TryActivateBossCoreSkill(b.RunId,8,u.EntityId),Is.EqualTo(SkillFailure.None));var start=b.BossRosterEvents.Single(e=>e.Kind=="SkillStart"&&e.SkillKey=="s2");b.Advance(16);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="StateStart"&&e.Animation=="Skill_2_Overload_Begin"),Is.True,"The second half enters its original overload transition.");Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="s2"&&e.HitIndex==3),Is.True,"Observe after the next legal attack and all four sub-shots, not during the transition.");b.Advance(10);var end=b.BossRosterEvents.Single(e=>e.Kind=="SkillEnd"&&e.SkillKey=="s2");Assert.That(end.ActivationId,Is.EqualTo(start.ActivationId));Assert.That(b.BossCoreState(u).ActiveUntil,Is.Zero);}
        [Test]public void SoulUsesFiveSpAutoSkillAndExactEarlyNativeContactWithRealFlight()
        {var b=Fixture("CARD_WISADEL_APRIL",out var u,"s1");b.Advance(4.9f);var soul=b.BossRosterObjects.Single(o=>o.Kind=="soul");Assert.That(b.BossCoreCamouflaged(u),Is.True);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="soul"),Is.False);b.Advance(.4f);var shot=b.BossRosterEvents.First(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="soul");Assert.That(shot.At-soul.AttackStartedAt,Is.EqualTo(.033333335).Within(.051));Assert.That(shot.EndAt-shot.At,Is.GreaterThan(0));Assert.That(soul.AnimationUntil-soul.AnimationAt,Is.EqualTo(2.0333333).Within(.0001));Assert.That(soul.Interaction,Is.EqualTo(BossObjectInteraction.Health));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="soul"&&e.Applied),Is.True);Assert.That(b.TryDamageBossRosterObject(b.RunId,soul.Id,soul.MaxHealth*2),Is.True);Assert.That(b.BossCoreCamouflaged(u),Is.False);}
        [Test]public void WinterScarRevivesOnceAndProtectsForTwentySimulationSeconds()
        {var b=Fixture("CARD_M14",out var u);b.Advance(1);Assert.That(b.Defender.ColdUntil,Is.GreaterThan(b.Clock));Assert.That(b.TryDamageUnit(u.EntityId,100000,CombatDamageType.Physical),Is.True);Assert.That(u.IsReviving,Is.True);double revivedAt=u.ReviveAt;b.Advance(5.1f);Assert.That(u.IsReviving,Is.False);Assert.That(b.BossCoreState(u).ProtectedUntil,Is.EqualTo(revivedAt+20));Assert.That(b.UnitInvulnerable(u),Is.True);Assert.That(b.BossRosterObjects.Any(o=>o.Kind=="iceCrystal"),Is.True);var crystal=b.BossRosterObjects.First(o=>o.Kind=="iceCrystal");Assert.That(b.TryDamageBossRosterObject(b.RunId,crystal.Id,100000),Is.False);b.SetPaused(true);double clock=b.Clock;b.Advance(60);Assert.That(b.Clock,Is.EqualTo(clock));b.SetPaused(false);b.Advance(20.1f);Assert.That(b.UnitInvulnerable(u),Is.False);Assert.That(b.BossRosterEvents.Any(e=>e.SkillKey=="coldWave"&&e.Kind=="StateStart"),Is.True);}
        [Test]public void TalulahBreathReducesOnlyItsActualMarkedAttackSource()
        {var b=Fixture("CARD_TALULAH_TRIAL",out var u);b.Advance(1);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="StateStart"&&e.SkillKey=="breath"&&e.TargetId==b.Defender.EntityId),Is.True);float before=u.Health;b.TryDamageUnit(u.EntityId,110,CombatDamageType.Physical,sourceDefender:b.Defender);float marked=before-u.Health;before=u.Health;b.TryDamageUnit(u.EntityId,110,CombatDamageType.Physical);float environment=before-u.Health;Assert.That(environment,Is.EqualTo(marked*2).Within(.001));float hp=b.Defender.Health;b.Advance(2);Assert.That(b.Defender.Health,Is.LessThan(hp));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="breath"&&e.Applied),Is.True);}
        [Test]public void TalulahSourceAutoActionDoesNotExtendTheIndependentManualSpLock()
        {var b=Fixture("CARD_TALULAH_TRIAL",out var u);b.Advance(18.5f);Assert.That(b.TryActivateSkill(b.RunId,40,u.EntityId),Is.EqualTo(SkillFailure.None));b.Advance(3.3f);Assert.That(u.SkillAmmo,Is.Zero);Assert.That(b.BossCoreFrame(u,out var raw,out var age,out var loop),Is.True);Assert.That(raw,Is.EqualTo("Skill_1_A"));Assert.That(b.IsSkillActionPlaying(u),Is.True,"The source action still locks the body.");Assert.That(u.SkillSP,Is.GreaterThan(0),"Only the completed manual rain, not a separate source passive, owns manual SP blocking.");float sp=u.SkillSP;b.Advance(.5f);Assert.That(u.SkillSP,Is.GreaterThan(sp));}
        [Test]public void WinterScarNativeBlackIceAndIceRingUseTheirDistinctSourceAbilities()
        {
            var black=Fixture("CARD_M14",out var first);first.NextIceRingAt=1000;black.BossCoreState(first).NextBlackIceAt=0;black.Advance(.1f);var cast=black.BossRosterEvents.Single(e=>e.Kind=="SkillStart"&&e.SkillKey=="blackIce");Assert.That(cast.NativeSkillKey,Is.EqualTo("IceShield"));Assert.That(cast.Animation,Is.EqualTo("Skill_1"));
            var ring=Fixture("CARD_M14",out var second);ring.TryDamageUnit(second.EntityId,100000,CombatDamageType.Physical);ring.Advance(5.1f);second.NextIceRingAt=ring.Clock;ring.Advance(.1f);var burst=ring.BossRosterEvents.Last(e=>e.Kind=="SkillStart"&&e.SkillKey=="iceRing");Assert.That(burst.NativeSkillKey,Is.EqualTo("IceBurst[Reborn]"));Assert.That(burst.Animation,Is.EqualTo("Skill_3"));Assert.That(burst.Phase,Is.EqualTo(2));Assert.That(ring.BossCoreFrame(second,out var raw,out var age,out var loop),Is.True);Assert.That(raw,Is.EqualTo("Skill_3"));
        }
        [Test]public void CoreNullAccessAndPreparationSelectionAreReadOnlyAndRestartSafe()
        {var b=Fixture("CARD_WISADEL_APRIL",out var ignored,"s2",false);Assert.That(b.BossCoreSkills(null),Is.Empty);Assert.That(b.BossCoreState(null),Is.Null);Assert.That(b.BossRosterObjects,Is.Empty);b.Begin();Assert.Throws<InvalidOperationException>(()=>b.ConfigureBossCoreViviSkill("s1"));b.Restart();Assert.That(b.BossCoreViviSkill,Is.EqualTo("s2"));}
    }
}
